import express from 'express';
import session from 'express-session';
import { scrypt, randomBytes, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

const scryptAsync = promisify(scrypt);

// --- password hashing (stdlib scrypt, per-password random salt) ---
async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scryptAsync(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return timingSafeEqual(key, await scryptAsync(password, salt, 64));
}

// chisle: in-memory users; swap for a DB lookup
const users = new Map([['alice', { id: 1, hash: await hashPassword('correct horse battery staple') }]]);
// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames.
const DUMMY_HASH = await hashPassword(randomBytes(16).toString('hex'));

// --- rate limiting: fixed window, per username and per IP ---
const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_USER = 5;
const MAX_PER_IP = 20;
// chisle: in-memory, single process; move to Redis when running >1 instance
const attempts = new Map(); // key -> { n, reset }

// Counts the attempt *before* the password check, so parallel requests can't all slip past the limit.
// Returns seconds to wait if over the limit, else 0.
function hit(key, max) {
  const now = Date.now();
  let a = attempts.get(key);
  if (!a || a.reset <= now) attempts.set(key, (a = { n: 0, reset: now + WINDOW_MS }));
  a.n++;
  return a.n > max ? Math.ceil((a.reset - now) / 1000) : 0;
}

setInterval(() => {
  const now = Date.now();
  for (const [k, a] of attempts) if (a.reset <= now) attempts.delete(k);
}, WINDOW_MS).unref();

